-- =============================================================================
-- Practice App — initial schema (schema version 1)
-- Target: Cloudflare D1 (SQLite). Files (HTML, images, fonts) live in R2,
-- keyed by their sha256; the database stores only the hash.
--
-- CONVENTIONS
--   IDs         TEXT ULID, generated by the app, never reused.
--               Lookup tables (difficulty, scoring_rule, error_type) use a short
--               fixed `code` as their ID; the display label is separate.
--   Times       INTEGER, Unix epoch milliseconds, UTC. Columns end in `_at`.
--   Durations   INTEGER whole seconds. Columns end in `_seconds`.
--   local_date  TEXT 'YYYY-MM-DD' = the learner's calendar day.
--   Booleans    INTEGER 0/1.
--   Scores      INTEGER permille (0..1000) so totals are exact and a rebuild
--               from history gives identical numbers.
--
-- WHAT THE DATABASE ENFORCES
--   Links (foreign keys), required values, allowed-value lists, numeric ranges,
--   and uniqueness. Everything else — versions not being edited, history being
--   add-only, frozen papers, archiving instead of deleting, writing change_log —
--   is the app's job.
-- =============================================================================

-- ---------------------------------------------------------------- schema meta
CREATE TABLE schema_migration (
  version      INTEGER PRIMARY KEY,
  name         TEXT    NOT NULL,
  applied_at   INTEGER NOT NULL,
  backup_ref   TEXT              -- R2 key of the pre-migration backup
) STRICT;

-- ---------------------------------------------------------------- blob store
-- One row per object in R2. R2 key = 'blob/' || sha256.
CREATE TABLE blob (
  sha256      TEXT    PRIMARY KEY,
  byte_size   INTEGER NOT NULL,
  mime_type   TEXT    NOT NULL,
  created_at  INTEGER NOT NULL
) STRICT, WITHOUT ROWID;

-- ---------------------------------------------------------------- import
-- The uploaded HTML file, kept byte-for-byte. Same bytes = same row.
CREATE TABLE source_file (
  id           TEXT    PRIMARY KEY,
  blob_sha256  TEXT    NOT NULL UNIQUE REFERENCES blob(sha256),
  file_name    TEXT    NOT NULL,
  created_at   INTEGER NOT NULL
) STRICT;

-- One committed import (the outcome of the review screen).
CREATE TABLE import_batch (
  id                 TEXT    PRIMARY KEY,
  source_file_id     TEXT    NOT NULL REFERENCES source_file(id),
  parser_version     TEXT    NOT NULL,
  found_count        INTEGER NOT NULL,
  new_count          INTEGER NOT NULL,
  new_version_count  INTEGER NOT NULL,
  duplicate_count    INTEGER NOT NULL,
  rejected_count     INTEGER NOT NULL,
  committed_at       INTEGER NOT NULL
) STRICT;
CREATE INDEX import_batch_by_file ON import_batch(source_file_id);

-- ---------------------------------------------------------------- taxonomy
CREATE TABLE subject (
  id           TEXT    PRIMARY KEY,
  name         TEXT    NOT NULL,
  created_at   INTEGER NOT NULL,
  archived_at  INTEGER
) STRICT;
CREATE UNIQUE INDEX subject_name_unique
  ON subject(name COLLATE NOCASE) WHERE archived_at IS NULL;

-- Concept tree (e.g. Maths → Algebra → Quadratics).
CREATE TABLE concept (
  id              TEXT    PRIMARY KEY,
  subject_id      TEXT    NOT NULL REFERENCES subject(id),
  parent_id       TEXT    REFERENCES concept(id),
  name            TEXT    NOT NULL,
  created_at      INTEGER NOT NULL,
  archived_at     INTEGER,
  merged_into_id  TEXT    REFERENCES concept(id)
) STRICT;
CREATE UNIQUE INDEX concept_sibling_name_unique
  ON concept(subject_id, ifnull(parent_id, ''), name COLLATE NOCASE)
  WHERE archived_at IS NULL;
CREATE INDEX concept_by_parent ON concept(parent_id);

-- Authored difficulty labels; sort_rank gives the numeric order.
CREATE TABLE difficulty (
  code         TEXT    PRIMARY KEY,
  label        TEXT    NOT NULL,
  sort_rank    INTEGER NOT NULL UNIQUE,
  archived_at  INTEGER
) STRICT, WITHOUT ROWID;

-- ---------------------------------------------------------------- questions
-- Permanent identity of a question + its editable metadata.
CREATE TABLE question (
  id               TEXT    PRIMARY KEY,
  subject_id       TEXT    REFERENCES subject(id),
  difficulty_code  TEXT    REFERENCES difficulty(code),
  answer_format    TEXT    NOT NULL DEFAULT 'none'
                   CHECK (answer_format IN ('none','mcq_single','mcq_multi','numeric','text')),
  option_labels    TEXT,   -- JSON array, e.g. ["A","B","C","D"]; MCQ only
  notes            TEXT,
  created_at       INTEGER NOT NULL,
  archived_at      INTEGER
) STRICT;
CREATE INDEX question_by_subject    ON question(subject_id);
CREATE INDEX question_by_difficulty ON question(difficulty_code);
CREATE INDEX question_by_created    ON question(created_at);

-- Content of a question at one point in time. Current = highest version_no.
CREATE TABLE question_version (
  id                      TEXT    PRIMARY KEY,
  question_id             TEXT    NOT NULL REFERENCES question(id),
  version_no              INTEGER NOT NULL CHECK (version_no >= 1),
  content_sha256          TEXT    NOT NULL UNIQUE,   -- same content never stored twice
  html_blob_sha256        TEXT    NOT NULL REFERENCES blob(sha256),
  plain_text              TEXT    NOT NULL,          -- for search
  import_batch_id         TEXT    NOT NULL REFERENCES import_batch(id),
  source_position         INTEGER NOT NULL,          -- 1st, 2nd… in the file
  source_question_number  TEXT    NOT NULL,          -- as printed in the file
  created_at              INTEGER NOT NULL,
  UNIQUE (question_id, version_no),
  UNIQUE (import_batch_id, source_position)
) STRICT;

-- Images/fonts/stylesheets a version refers to. blob_sha256 NULL = missing.
CREATE TABLE question_version_asset (
  question_version_id  TEXT NOT NULL REFERENCES question_version(id),
  original_ref         TEXT NOT NULL,
  role                 TEXT NOT NULL CHECK (role IN ('image','font','stylesheet','other')),
  blob_sha256          TEXT REFERENCES blob(sha256),
  PRIMARY KEY (question_version_id, original_ref)
) STRICT, WITHOUT ROWID;
CREATE INDEX question_version_asset_missing
  ON question_version_asset(question_version_id) WHERE blob_sha256 IS NULL;

-- Approved concept tags with weights.
CREATE TABLE question_concept (
  question_id  TEXT    NOT NULL REFERENCES question(id),
  concept_id   TEXT    NOT NULL REFERENCES concept(id),
  weight       REAL    NOT NULL CHECK (weight > 0.0 AND weight <= 1.0),
  created_at   INTEGER NOT NULL,
  PRIMARY KEY (question_id, concept_id)
) STRICT, WITHOUT ROWID;
CREATE INDEX question_concept_by_concept ON question_concept(concept_id, weight, question_id);

-- ---------------------------------------------------------------- custom fields
CREATE TABLE custom_field (
  id             TEXT    PRIMARY KEY,
  name           TEXT    NOT NULL,
  data_type      TEXT    NOT NULL CHECK (data_type IN ('text','number','date','boolean')),
  is_filterable  INTEGER NOT NULL DEFAULT 0 CHECK (is_filterable IN (0,1)),
  created_at     INTEGER NOT NULL,
  archived_at    INTEGER
) STRICT;
CREATE UNIQUE INDEX custom_field_name_unique
  ON custom_field(name COLLATE NOCASE) WHERE archived_at IS NULL;

-- Exactly one value column is filled. "No value" = no row.
CREATE TABLE question_field_value (
  question_id   TEXT    NOT NULL REFERENCES question(id),
  field_id      TEXT    NOT NULL REFERENCES custom_field(id),
  value_text    TEXT,
  value_number  REAL,
  value_date    TEXT,     -- 'YYYY-MM-DD'
  value_bool    INTEGER CHECK (value_bool IN (0,1)),
  updated_at    INTEGER NOT NULL,
  PRIMARY KEY (question_id, field_id),
  CHECK ((value_text IS NOT NULL) + (value_number IS NOT NULL)
       + (value_date IS NOT NULL) + (value_bool IS NOT NULL) = 1)
) STRICT, WITHOUT ROWID;
CREATE INDEX question_field_value_text   ON question_field_value(field_id, value_text)   WHERE value_text   IS NOT NULL;
CREATE INDEX question_field_value_number ON question_field_value(field_id, value_number) WHERE value_number IS NOT NULL;
CREATE INDEX question_field_value_date   ON question_field_value(field_id, value_date)   WHERE value_date   IS NOT NULL;
CREATE INDEX question_field_value_bool   ON question_field_value(field_id, value_bool)   WHERE value_bool   IS NOT NULL;

-- ---------------------------------------------------------------- keys & solutions
-- Verified answer key for one question version. To change a key, retire the
-- old row and add a new one, so each grade points at the key that produced it.
CREATE TABLE answer_key (
  id                   TEXT    PRIMARY KEY,
  question_version_id  TEXT    NOT NULL REFERENCES question_version(id),
  key_no               INTEGER NOT NULL CHECK (key_no >= 1),
  answer_type          TEXT    NOT NULL
                       CHECK (answer_type IN ('mcq_single','mcq_multi','numeric','text')),
  mcq_correct          TEXT,   -- JSON array of option labels
  numeric_value        REAL,
  numeric_tolerance    REAL    CHECK (numeric_tolerance >= 0.0),
  text_value           TEXT,
  origin               TEXT    NOT NULL CHECK (origin IN ('manual','import','suggestion')),
  created_at           INTEGER NOT NULL,
  retired_at           INTEGER,
  UNIQUE (question_version_id, key_no),
  CHECK (answer_type NOT IN ('mcq_single','mcq_multi') OR mcq_correct IS NOT NULL),
  CHECK (answer_type <> 'numeric' OR (numeric_value IS NOT NULL AND numeric_tolerance IS NOT NULL)),
  CHECK (answer_type <> 'text' OR text_value IS NOT NULL)
) STRICT;
CREATE UNIQUE INDEX answer_key_one_active
  ON answer_key(question_version_id) WHERE retired_at IS NULL;

CREATE TABLE solution (
  id                   TEXT    PRIMARY KEY,
  question_version_id  TEXT    NOT NULL REFERENCES question_version(id),
  solution_no          INTEGER NOT NULL CHECK (solution_no >= 1),
  body_text            TEXT,
  body_blob_sha256     TEXT    REFERENCES blob(sha256),
  origin               TEXT    NOT NULL CHECK (origin IN ('manual','import','suggestion')),
  created_at           INTEGER NOT NULL,
  retired_at           INTEGER,
  UNIQUE (question_version_id, solution_no),
  CHECK ((body_text IS NOT NULL) + (body_blob_sha256 IS NOT NULL) = 1)
) STRICT;
CREATE UNIQUE INDEX solution_one_active
  ON solution(question_version_id) WHERE retired_at IS NULL;

-- AI proposals, kept apart until approved.
CREATE TABLE suggestion (
  id                   TEXT    PRIMARY KEY,
  question_id          TEXT    NOT NULL REFERENCES question(id),
  question_version_id  TEXT    REFERENCES question_version(id),
  kind                 TEXT    NOT NULL
                       CHECK (kind IN ('subject','difficulty','concept','answer_key','solution')),
  payload              TEXT    NOT NULL,   -- JSON
  source               TEXT    NOT NULL,   -- e.g. model name
  status               TEXT    NOT NULL DEFAULT 'unverified'
                       CHECK (status IN ('unverified','approved','corrected','rejected')),
  created_at           INTEGER NOT NULL,
  decided_at           INTEGER
) STRICT;
CREATE INDEX suggestion_open ON suggestion(question_id) WHERE status = 'unverified';

-- ---------------------------------------------------------------- filters & papers
-- definition = AND/OR tree as JSON; dates inside are relative ("last 30 days").
CREATE TABLE saved_filter (
  id           TEXT    PRIMARY KEY,
  name         TEXT    NOT NULL,
  definition   TEXT    NOT NULL,
  created_at   INTEGER NOT NULL,
  updated_at   INTEGER NOT NULL,
  archived_at  INTEGER
) STRICT;
CREATE UNIQUE INDEX saved_filter_name_unique
  ON saved_filter(name COLLATE NOCASE) WHERE archived_at IS NULL;

-- Paper = filter + sampling settings + seed, frozen into a fixed list.
-- frozen_at NULL = draft (can still be reordered / edited).
CREATE TABLE paper (
  id                 TEXT    PRIMARY KEY,
  name               TEXT    NOT NULL,
  saved_filter_id    TEXT    REFERENCES saved_filter(id),
  filter_definition  TEXT    NOT NULL,   -- own copy of the filter
  sampling_settings  TEXT    NOT NULL,
  seed               INTEGER NOT NULL,
  generator_version  INTEGER NOT NULL,
  requested_count    INTEGER NOT NULL CHECK (requested_count >= 1),
  created_at         INTEGER NOT NULL,
  frozen_at          INTEGER,
  archived_at        INTEGER
) STRICT;
CREATE INDEX paper_by_created ON paper(created_at);

-- The fixed list, pinned to exact question versions.
CREATE TABLE paper_item (
  paper_id             TEXT    NOT NULL REFERENCES paper(id) ON DELETE CASCADE,
  position             INTEGER NOT NULL CHECK (position >= 1),
  question_id          TEXT    NOT NULL REFERENCES question(id),
  question_version_id  TEXT    NOT NULL REFERENCES question_version(id),
  pick_reason          TEXT,   -- JSON: which target it fills, its score
  PRIMARY KEY (paper_id, position),
  UNIQUE (paper_id, question_id)          -- never repeat a question in one paper
) STRICT, WITHOUT ROWID;
CREATE INDEX paper_item_by_question ON paper_item(question_id);

-- One sitting of a paper; holds pause/resume state. No time limits.
CREATE TABLE practice_session (
  id                       TEXT    PRIMARY KEY,
  paper_id                 TEXT    NOT NULL REFERENCES paper(id),
  started_at               INTEGER NOT NULL,
  completed_at             INTEGER,
  current_position         INTEGER NOT NULL DEFAULT 1,
  current_elapsed_seconds  INTEGER NOT NULL DEFAULT 0,
  updated_at               INTEGER NOT NULL
) STRICT;
CREATE UNIQUE INDEX practice_session_one_open
  ON practice_session(paper_id) WHERE completed_at IS NULL;

-- ---------------------------------------------------------------- history
CREATE TABLE scoring_rule (
  code         TEXT PRIMARY KEY,
  method       TEXT NOT NULL CHECK (method IN ('manual','auto')),
  description  TEXT NOT NULL
) STRICT, WITHOUT ROWID;

CREATE TABLE error_type (
  code         TEXT    PRIMARY KEY,
  label        TEXT    NOT NULL,
  archived_at  INTEGER
) STRICT, WITHOUT ROWID;

-- One answer to one question version.
CREATE TABLE attempt (
  id                   TEXT    PRIMARY KEY,
  question_id          TEXT    NOT NULL REFERENCES question(id),
  question_version_id  TEXT    NOT NULL REFERENCES question_version(id),
  session_id           TEXT    REFERENCES practice_session(id),
  paper_id             TEXT    REFERENCES paper(id),
  paper_position       INTEGER,
  attempted_at         INTEGER NOT NULL,
  local_date           TEXT    NOT NULL,
  time_taken_seconds   INTEGER NOT NULL CHECK (time_taken_seconds >= 0),
  response_kind        TEXT    NOT NULL CHECK (response_kind IN ('none','mcq','numeric','text')),
  response_options     TEXT,   -- JSON array
  response_numeric     REAL,
  response_text        TEXT
) STRICT;
CREATE INDEX attempt_by_question ON attempt(question_id, attempted_at);
CREATE INDEX attempt_by_day      ON attempt(local_date);
CREATE UNIQUE INDEX attempt_once_per_session_item
  ON attempt(session_id, paper_position) WHERE session_id IS NOT NULL;

-- A judgement on an attempt. A correction is a new row with the next grade_no;
-- the highest grade_no counts.
CREATE TABLE grade (
  id                 TEXT    PRIMARY KEY,
  attempt_id         TEXT    NOT NULL REFERENCES attempt(id),
  grade_no           INTEGER NOT NULL CHECK (grade_no >= 1),
  cause              TEXT    NOT NULL CHECK (cause IN ('initial','correction','auto_regrade')),
  result             TEXT    NOT NULL CHECK (result IN ('correct','incorrect','partial')),
  score_permille     INTEGER NOT NULL CHECK (score_permille BETWEEN 0 AND 1000),
  method             TEXT    NOT NULL CHECK (method IN ('manual','auto')),
  scoring_rule_code  TEXT    NOT NULL REFERENCES scoring_rule(code),
  answer_key_id      TEXT    REFERENCES answer_key(id),
  error_type_code    TEXT    REFERENCES error_type(code),
  confidence         INTEGER CHECK (confidence BETWEEN 1 AND 5),
  note               TEXT,
  graded_at          INTEGER NOT NULL,
  UNIQUE (attempt_id, grade_no),
  CHECK (method <> 'auto' OR answer_key_id IS NOT NULL),
  CHECK ((result = 'correct'   AND score_permille = 1000)
      OR (result = 'incorrect' AND score_permille = 0)
      OR (result = 'partial'   AND score_permille BETWEEN 1 AND 999))
) STRICT;
CREATE INDEX grade_by_key ON grade(answer_key_id) WHERE answer_key_id IS NOT NULL;

-- ---------------------------------------------------------------- change log
-- Metadata edits (old value → new value). Written by the app in the same
-- batch as the edit.
CREATE TABLE change_log (
  id           INTEGER PRIMARY KEY,
  table_name   TEXT    NOT NULL,
  row_key      TEXT    NOT NULL,   -- row id; 'a|b' for two-column keys
  column_name  TEXT    NOT NULL,
  op           TEXT    NOT NULL CHECK (op IN ('insert','update','delete')),
  old_value    TEXT,
  new_value    TEXT,
  changed_at   INTEGER NOT NULL
) STRICT;
CREATE INDEX change_log_by_row ON change_log(table_name, row_key, id);

-- ---------------------------------------------------------------- derived metrics
-- Updated in the same batch as each grade; can be rebuilt from history.
-- No row = never attempted.
CREATE TABLE question_stat (
  question_id                   TEXT    PRIMARY KEY REFERENCES question(id),
  attempt_count                 INTEGER NOT NULL,
  graded_count                  INTEGER NOT NULL,
  correct_count                 INTEGER NOT NULL,
  incorrect_count               INTEGER NOT NULL,
  partial_count                 INTEGER NOT NULL,
  score_permille_sum            INTEGER NOT NULL,
  total_time_seconds            INTEGER NOT NULL,   -- average = total / attempt_count
  last_attempt_id               TEXT    NOT NULL REFERENCES attempt(id),
  last_attempted_at             INTEGER NOT NULL,
  last_time_seconds             INTEGER NOT NULL,
  last_result                   TEXT    CHECK (last_result IN ('correct','incorrect','partial')),
  personal_difficulty_permille  INTEGER CHECK (personal_difficulty_permille BETWEEN 0 AND 1000),
  familiarity_permille          INTEGER NOT NULL CHECK (familiarity_permille BETWEEN 0 AND 1000),
  algo_version                  INTEGER NOT NULL
) STRICT, WITHOUT ROWID;
CREATE INDEX question_stat_by_last_attempt ON question_stat(last_attempted_at);
CREATE INDEX question_stat_by_last_result  ON question_stat(last_result);

-- Per concept per day: accuracy = score_weight_sum / weight_sum.
-- weight_milli = round(weight * 1000).
CREATE TABLE concept_daily_stat (
  concept_id         TEXT    NOT NULL REFERENCES concept(id),
  local_date         TEXT    NOT NULL,
  graded_count       INTEGER NOT NULL,
  weight_sum         INTEGER NOT NULL,   -- sum(weight_milli)
  score_weight_sum   INTEGER NOT NULL,   -- sum(weight_milli * score_permille)
  PRIMARY KEY (concept_id, local_date)
) STRICT, WITHOUT ROWID;

CREATE TABLE subject_daily_stat (
  subject_id          TEXT    NOT NULL REFERENCES subject(id),
  local_date          TEXT    NOT NULL,
  graded_count        INTEGER NOT NULL,
  score_permille_sum  INTEGER NOT NULL,
  PRIMARY KEY (subject_id, local_date)
) STRICT, WITHOUT ROWID;

-- ---------------------------------------------------------------- integrity runs
CREATE TABLE integrity_check_run (
  id            TEXT    PRIMARY KEY,
  reason        TEXT    NOT NULL CHECK (reason IN ('manual','restore','migration','scheduled')),
  started_at    INTEGER NOT NULL,
  finished_at   INTEGER NOT NULL,
  issue_count   INTEGER NOT NULL,
  report        TEXT    NOT NULL   -- JSON
) STRICT;

-- ---------------------------------------------------------------- views
CREATE VIEW v_question_current AS
SELECT q.*, v.id AS version_id, v.version_no, v.content_sha256,
       v.html_blob_sha256, v.plain_text, v.import_batch_id,
       v.source_position, v.source_question_number
FROM question q
JOIN question_version v
  ON v.question_id = q.id
 AND v.version_no = (SELECT max(version_no) FROM question_version WHERE question_id = q.id);

CREATE VIEW v_effective_grade AS
SELECT g.*
FROM grade g
WHERE g.grade_no = (SELECT max(grade_no) FROM grade WHERE attempt_id = g.attempt_id);

CREATE VIEW v_daily_activity AS
SELECT local_date, count(*) AS attempt_count, sum(time_taken_seconds) AS time_seconds
FROM attempt
GROUP BY local_date;

